This Terraform configuration provisions an AWS RDS PostgreSQL database using the `db.t4g.large` instance class. It uses the default VPC and its subnets, creates a DB subnet group, provisions a security group allowing PostgreSQL access on port `5432`, generates a secure master password, and creates an encrypted PostgreSQL RDS instance.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the PostgreSQL RDS instance will be created."
  type        = string
  default     = "us-east-1"
}

variable "db_identifier" {
  description = "The identifier for the RDS PostgreSQL instance."
  type        = string
  default     = "postgres-t4g-large-db"
}

